contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        require(true);

        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!initReverted && minSumAfter == 0);
    }

    receive() external payable {}
}

